PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "tbl_pos_password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "tbl_sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "tbl_pos_cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "tbl_pos_cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "tbl_pos_jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "tbl_pos_job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "tbl_pos_failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "tbl_pos_stores" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "alternate_phone" varchar, "address" varchar, "city" varchar, "state" varchar, "pincode" varchar, "gstin" varchar, "fssai_license" varchar, "upi_vpa" varchar, "currency" varchar not null default 'INR', "default_gst_rate" numeric not null default '5', "is_gst_enabled" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "print_header" varchar, "print_footer" varchar, "logo_path" varchar, "owner_user_id" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "tbl_pos_users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "store_id" integer, "role" varchar check ("role" in ('admin', 'cashier')) not null default 'cashier', "phone" varchar, "is_active" tinyint(1) not null default '1', "last_login_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tbl_pos_categories" ("id" integer primary key autoincrement not null, "store_id" integer not null, "name" varchar not null, "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "uuid" varchar, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tbl_pos_food_items" ("id" integer primary key autoincrement not null, "store_id" integer not null, "category_id" integer, "name" varchar not null, "price" numeric not null default '0', "is_available" tinyint(1) not null default '1', "food_type" varchar check ("food_type" in ('veg', 'non_veg', 'egg')) not null default 'veg', "gst_rate" integer not null default '5', "sort_order" integer not null default '0', "uuid" varchar, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade, foreign key("category_id") references "tbl_categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tbl_pos_orders" ("id" integer primary key autoincrement not null, "store_id" integer not null, "user_id" integer, "order_number" varchar not null, "subtotal" numeric not null default '0', "discount_amount" numeric not null default '0', "tax_amount" numeric not null default '0', "round_off" numeric not null default '0', "total_amount" numeric not null default '0', "payment_mode" varchar check ("payment_mode" in ('cash', 'upi', 'card', 'credit', 'split')) not null default 'cash', "payment_status" varchar check ("payment_status" in ('paid', 'unpaid', 'partial')) not null default 'paid', "status" varchar check ("status" in ('pending', 'preparing', 'ready', 'completed', 'cancelled')) not null default 'completed', "order_type" varchar check ("order_type" in ('dine_in', 'takeaway', 'parcel', 'delivery')) not null default 'takeaway', "upi_ref" varchar, "invoice_number" varchar, "customer_name" varchar, "customer_phone" varchar, "idempotency_key" varchar, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade, foreign key("user_id") references "tbl_users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tbl_pos_order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "food_item_id" integer, "food_item_name" varchar not null, "quantity" integer not null default '1', "price" numeric not null default '0', "subtotal" numeric not null default '0', "discount_amount" numeric not null default '0', "gst_rate" integer not null default '5', "gst_amount" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "tbl_orders"("id") on delete cascade, foreign key("food_item_id") references "tbl_food_items"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tbl_pos_store_devices" ("id" integer primary key autoincrement not null, "store_id" integer not null, "user_id" integer, "device_id" varchar not null, "platform" varchar not null default 'android', "app_version" varchar, "fcm_token" text, "last_sync_at" datetime, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade, foreign key("user_id") references "tbl_users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tbl_pos_payments" ("id" integer primary key autoincrement not null, "store_id" integer not null, "order_id" integer not null, "mode" varchar not null default 'cash', "amount" numeric not null default '0', "status" varchar not null default 'success', "upi_ref" varchar, "upi_txn_id" varchar, "vpa" varchar, "provider" varchar, "provider_payload" text, "notes" text, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade, foreign key("order_id") references "tbl_orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tbl_pos_sync_queue" ("id" integer primary key autoincrement not null, "store_id" integer not null, "user_id" integer, "device_id" varchar, "action" varchar not null, "idempotency_key" varchar not null, "payload" text not null, "status" varchar not null default 'queued', "attempts" integer not null default '0', "error" text, "applied_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade, foreign key("user_id") references "tbl_users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tbl_pos_audit_logs" ("id" integer primary key autoincrement not null, "store_id" integer not null, "user_id" integer, "user_name" varchar, "action" varchar not null, "entity_type" varchar, "entity_id" integer, "entity_name" varchar, "description" text not null, "old_values" text, "new_values" text, "amount" numeric, "ip_address" varchar, "created_at" datetime, "updated_at" datetime, foreign key("store_id") references "tbl_stores"("id") on delete cascade, foreign key("user_id") references "tbl_users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tbl_pos_personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "tbl_sessions_user_id_index" on "tbl_sessions" ("user_id");
CREATE INDEX "tbl_sessions_last_activity_index" on "tbl_sessions" ("last_activity");
CREATE INDEX "tbl_jobs_queue_index" on "tbl_pos_jobs" ("queue");
CREATE UNIQUE INDEX "tbl_failed_jobs_uuid_unique" on "tbl_pos_failed_jobs" ("uuid");
CREATE INDEX "tbl_stores_city_index" on "tbl_pos_stores" ("city");
CREATE INDEX "tbl_stores_state_index" on "tbl_pos_stores" ("state");
CREATE INDEX "tbl_stores_pincode_index" on "tbl_pos_stores" ("pincode");
CREATE INDEX "tbl_stores_gstin_index" on "tbl_pos_stores" ("gstin");
CREATE INDEX "tbl_stores_is_gst_enabled_index" on "tbl_pos_stores" ("is_gst_enabled");
CREATE INDEX "tbl_stores_is_active_index" on "tbl_pos_stores" ("is_active");
CREATE UNIQUE INDEX "tbl_users_email_unique" on "tbl_pos_users" ("email");
CREATE INDEX "tbl_users_store_id_index" on "tbl_pos_users" ("store_id");
CREATE INDEX "tbl_users_role_index" on "tbl_pos_users" ("role");
CREATE INDEX "tbl_users_is_active_index" on "tbl_pos_users" ("is_active");
CREATE INDEX "tbl_categories_store_id_name_index" on "tbl_pos_categories" ("store_id", "name");
CREATE INDEX "tbl_categories_store_id_index" on "tbl_pos_categories" ("store_id");
CREATE INDEX "tbl_categories_is_active_index" on "tbl_pos_categories" ("is_active");
CREATE INDEX "tbl_categories_sort_order_index" on "tbl_pos_categories" ("sort_order");
CREATE UNIQUE INDEX "tbl_categories_uuid_unique" on "tbl_pos_categories" ("uuid");
CREATE INDEX "tbl_food_items_store_id_category_id_index" on "tbl_pos_food_items" ("store_id", "category_id");
CREATE INDEX "tbl_food_items_store_id_index" on "tbl_pos_food_items" ("store_id");
CREATE INDEX "tbl_food_items_is_available_index" on "tbl_pos_food_items" ("is_available");
CREATE INDEX "tbl_food_items_food_type_index" on "tbl_pos_food_items" ("food_type");
CREATE INDEX "tbl_food_items_sort_order_index" on "tbl_pos_food_items" ("sort_order");
CREATE UNIQUE INDEX "tbl_food_items_uuid_unique" on "tbl_pos_food_items" ("uuid");
CREATE INDEX "tbl_orders_store_id_created_at_index" on "tbl_pos_orders" ("store_id", "created_at");
CREATE UNIQUE INDEX "tbl_orders_store_id_order_number_unique" on "tbl_pos_orders" ("store_id", "order_number");
CREATE INDEX "tbl_orders_store_id_index" on "tbl_pos_orders" ("store_id");
CREATE INDEX "tbl_orders_order_number_index" on "tbl_pos_orders" ("order_number");
CREATE INDEX "tbl_orders_payment_status_index" on "tbl_pos_orders" ("payment_status");
CREATE INDEX "tbl_orders_status_index" on "tbl_pos_orders" ("status");
CREATE INDEX "tbl_orders_order_type_index" on "tbl_pos_orders" ("order_type");
CREATE INDEX "tbl_orders_upi_ref_index" on "tbl_pos_orders" ("upi_ref");
CREATE INDEX "tbl_orders_invoice_number_index" on "tbl_pos_orders" ("invoice_number");
CREATE INDEX "tbl_orders_customer_phone_index" on "tbl_pos_orders" ("customer_phone");
CREATE UNIQUE INDEX "tbl_orders_idempotency_key_unique" on "tbl_pos_orders" ("idempotency_key");
CREATE INDEX "tbl_order_items_order_id_index" on "tbl_pos_order_items" ("order_id");
CREATE UNIQUE INDEX "tbl_store_devices_store_id_device_id_unique" on "tbl_pos_store_devices" ("store_id", "device_id");
CREATE INDEX "tbl_store_devices_store_id_index" on "tbl_pos_store_devices" ("store_id");
CREATE INDEX "tbl_store_devices_device_id_index" on "tbl_pos_store_devices" ("device_id");
CREATE INDEX "tbl_store_devices_platform_index" on "tbl_pos_store_devices" ("platform");
CREATE INDEX "tbl_store_devices_last_sync_at_index" on "tbl_pos_store_devices" ("last_sync_at");
CREATE INDEX "tbl_store_devices_is_active_index" on "tbl_pos_store_devices" ("is_active");
CREATE INDEX "tbl_payments_store_id_created_at_index" on "tbl_pos_payments" ("store_id", "created_at");
CREATE INDEX "tbl_payments_store_id_index" on "tbl_pos_payments" ("store_id");
CREATE INDEX "tbl_payments_order_id_index" on "tbl_pos_payments" ("order_id");
CREATE INDEX "tbl_payments_mode_index" on "tbl_pos_payments" ("mode");
CREATE INDEX "tbl_payments_status_index" on "tbl_pos_payments" ("status");
CREATE INDEX "tbl_payments_upi_ref_index" on "tbl_pos_payments" ("upi_ref");
CREATE INDEX "tbl_payments_upi_txn_id_index" on "tbl_pos_payments" ("upi_txn_id");
CREATE INDEX "tbl_payments_provider_index" on "tbl_pos_payments" ("provider");
CREATE INDEX "tbl_payments_paid_at_index" on "tbl_pos_payments" ("paid_at");
CREATE INDEX "tbl_sync_queue_store_id_status_index" on "tbl_pos_sync_queue" ("store_id", "status");
CREATE INDEX "tbl_sync_queue_store_id_index" on "tbl_pos_sync_queue" ("store_id");
CREATE INDEX "tbl_sync_queue_device_id_index" on "tbl_pos_sync_queue" ("device_id");
CREATE INDEX "tbl_sync_queue_action_index" on "tbl_pos_sync_queue" ("action");
CREATE UNIQUE INDEX "tbl_sync_queue_idempotency_key_unique" on "tbl_pos_sync_queue" ("idempotency_key");
CREATE INDEX "tbl_sync_queue_status_index" on "tbl_pos_sync_queue" ("status");
CREATE INDEX "tbl_sync_queue_applied_at_index" on "tbl_pos_sync_queue" ("applied_at");
CREATE INDEX "tbl_audit_logs_store_id_action_index" on "tbl_pos_audit_logs" ("store_id", "action");
CREATE INDEX "tbl_audit_logs_store_id_created_at_index" on "tbl_pos_audit_logs" ("store_id", "created_at");
CREATE INDEX "tbl_audit_logs_store_id_user_id_index" on "tbl_pos_audit_logs" ("store_id", "user_id");
CREATE INDEX "tbl_audit_logs_store_id_index" on "tbl_pos_audit_logs" ("store_id");
CREATE INDEX "tbl_audit_logs_action_index" on "tbl_pos_audit_logs" ("action");
CREATE INDEX "tbl_audit_logs_entity_type_index" on "tbl_pos_audit_logs" ("entity_type");
CREATE INDEX "tbl_audit_logs_entity_id_index" on "tbl_pos_audit_logs" ("entity_id");
CREATE INDEX "tbl_personal_access_tokens_tokenable_type_tokenable_id_index" on "tbl_pos_personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "tbl_personal_access_tokens_token_unique" on "tbl_pos_personal_access_tokens" ("token");
CREATE INDEX "tbl_personal_access_tokens_expires_at_index" on "tbl_pos_personal_access_tokens" ("expires_at");
COMMIT;
